/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { ApproachScreen } from "../../src/approach/ApproachScreen.js";
import EquilibriumLabColors from "../../src/EquilibriumLabColors.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { ICETableScreen } from "../../src/ice-table/ICETableScreen.js";
import { LeChatelierScreen } from "../../src/le-chatelier/LeChatelierScreen.js";
import { EquilibriumLabPreferencesModel } from "../../src/preferences/EquilibriumLabPreferencesModel.js";
import { VantHoffScreen } from "../../src/vant-hoff/VantHoffScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from equilibriumLabQueryParameters.
  const simPreferences = new EquilibriumLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new ApproachScreen({
      name: stringManager.getScreenNames().approachStringProperty,
      startWithKpProperty: simPreferences.startWithKpProperty,
      showReactionFlashesProperty: simPreferences.showReactionFlashesProperty,
      tandem: Tandem.ROOT.createTandem("approachScreen"),
      backgroundColorProperty: EquilibriumLabColors.backgroundColorProperty,
    }),
    new ICETableScreen({
      name: stringManager.getScreenNames().iceTableStringProperty,
      tandem: Tandem.ROOT.createTandem("iceTableScreen"),
      backgroundColorProperty: EquilibriumLabColors.backgroundColorProperty,
    }),
    new LeChatelierScreen({
      name: stringManager.getScreenNames().leChatelierStringProperty,
      startWithKpProperty: simPreferences.startWithKpProperty,
      showReactionFlashesProperty: simPreferences.showReactionFlashesProperty,
      tandem: Tandem.ROOT.createTandem("leChatelierScreen"),
      backgroundColorProperty: EquilibriumLabColors.backgroundColorProperty,
    }),
    new VantHoffScreen({
      name: stringManager.getScreenNames().vantHoffStringProperty,
      showReactionFlashesProperty: simPreferences.showReactionFlashesProperty,
      tandem: Tandem.ROOT.createTandem("vantHoffScreen"),
      backgroundColorProperty: EquilibriumLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { EquilibriumLabColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
